def tag_resource(self, resource_arn: str, tags: List[Dict[str, str]]) -> None:
    if len(tags) > 0:
        resource = self._get_resource_with_arn(resource_arn=resource_arn)

        # Create a dictionary of existing tags for easy lookup
        existing_tags = {tag['key']: tag for tag in resource.tags}

        # Update existing tags or add new ones
        for tag in tags:
            if tag['key'] in existing_tags:
                # Update existing tag
                existing_tags[tag['key']]['value'] = tag['value']
            else:
                # Add new tag
                resource.tags.append(tag)
    return

