def _get_resource_with_arn(self, resource_arn: str) -> Union[Mesh, VirtualRouter, Route, VirtualNode]:
    # Check for mesh resources
    for mesh in self.meshes.values():
        if mesh.metadata.arn == resource_arn:
            return mesh

        # Check for virtual router resources
        for router in mesh.virtual_routers.values():
            if router.metadata.arn == resource_arn:
                return router

            # Check for route resources
            for route in router.routes.values():
                if route.metadata.arn == resource_arn:
                    return route

        # Check for virtual node resources
        for node in mesh.virtual_nodes.values():
            if node.metadata.arn == resource_arn:
                return node

    raise ResourceNotFoundError(resource_arn)
